class Solution:
    def countSubstrings(self, s: str) -> int:
        n = len(s)
        dp = [False] * n
        count = 0

        for l in range(n - 1, -1, -1):
            new_dp = [False] * n
            for r in range(l, n):
                new_dp[r] = s[l] == s[r] and (r - l < 2 or dp[r - 1])
                if new_dp[r]:
                    count += 1
            dp = new_dp

        return count

